package uk.co.renbinden.vantage.auth

import java.io.File

/**
 * Tracks the `./private.pem` signing key that constructing an [Authenticator] reads, or generates
 * when it is missing. Call [beforeAll] before the first [Authenticator] is constructed and
 * [afterAll] once a test class is done, so a key generated by the tests is removed again while a
 * pre-existing key in the working directory is left in place.
 */
object PrivateKeyFile {

    val file = File("./private.pem")

    var createdByTests = false
        private set

    fun beforeAll() {
        createdByTests = !file.exists()
    }

    fun afterAll() {
        if (createdByTests) file.delete()
    }

}
